contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        uint preDepositContractBalance = address(c).balance;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint beforeCollectBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCollectContractBalance = address(c).balance;
        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;

        require(beforeCollectBalance >= minSum, "balance must be at least MinSum for collect to succeed");

        bool collectReverted;
        c.Collect(depositAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        uint afterCollectBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterCollectContractBalance = address(c).balance;

        assert(!collectReverted && afterCollectBalance == beforeCollectBalance - depositAmount && afterCollectContractBalance == beforeCollectContractBalance - depositAmount);
    }

    receive() external payable {}
}

