pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint preDepositContractBalance = address(c).balance;
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 beforeCollectBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeCollectBalance = __r; } catch { return; }
        uint beforeCollectContractBalance = address(c).balance;
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        vm.assume(beforeCollectBalance >= minSum);
        bool collectReverted;
        try c.Collect(depositAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 afterCollectBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterCollectBalance = __r; } catch { return; }
        uint afterCollectContractBalance = address(c).balance;
        assertTrue(!collectReverted && afterCollectBalance == beforeCollectBalance - depositAmount && afterCollectContractBalance == beforeCollectContractBalance - depositAmount);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
